hermes_script:
#!/bin/sh
log="$FAKE_HERMES_LOG"
{
  printf 'argc=%s\n' "$#"
  for a in "$@"; do printf 'arg<<%s>>\n' "$a"; done
  if IFS= read -r _line; then printf 'stdin=data\n'; else printf 'stdin=eof\n'; fi
} >> "$log"
case "$FAKE_HERMES_MODE" in
  ok) printf 'rewritten <text> & more\n\n' ;;
  fail) printf 'bad\n' >&2; exit 4 ;;
  empty) : ;;
  *) exit 9 ;;
esac

